from pathlib import Path
import pandas as pd,numpy as np,json
O=Path('outputs');W=Path('work');x=pd.read_csv(O/'stage6_rbm6_gtex_mvp_aligned.csv');o=pd.read_csv(W/'stage6_rbm6_mvp_original_region.tsv.gz',sep='\t');o=o.rename(columns={'base_pair_location':'position','effect_allele':'orig_ea','other_allele':'orig_oa','odds_ratio':'orig_or','p_value':'orig_p','effect_allele_frequency':'orig_af'});o['pair']=o.apply(lambda r:''.join(sorted([str(r.orig_ea),str(r.orig_oa)])),axis=1);o=o.drop_duplicates(['position','pair'],keep=False);m=x.merge(o,on=['position','pair'],validate='one_to_one');ex=np.where(m.orig_ea==m.mvp_ea,m.orig_or,1/m.orig_or);af=np.where(m.orig_ea==m.mvp_ea,m.orig_af,1-m.orig_af);vals={'retained':len(x),'exact_original_matches':len(m),'maximum_or_difference':float(np.max(abs(ex-m.mvp_odds_ratio))),'maximum_p_difference':float(np.max(abs(m.orig_p-m.mvp_p))),'maximum_frequency_difference':float(np.max(abs(af-m.mvp_eaf)))};assert len(m)==len(x) and max(vals['maximum_or_difference'],vals['maximum_p_difference'],vals['maximum_frequency_difference'])<1e-10;(O/'stage6_rbm6_mvp_source_consistency_receipt.json').write_text(json.dumps(vals,indent=2)+'\n');print(json.dumps(vals,indent=2))
